import random

# Load valid words
with open('/workdir/valid_words.txt', 'r') as f:
    valid_words = set(line.strip() for line in f)

print(f"Loaded {len(valid_words)} valid words")

def generate_derangement():
    """Generate a random derangement"""
    # Start with identity
    perm = list(range(26))
    # Shuffle it
    random.shuffle(perm)
    # Fix any fixed points (where perm[i] == i)
    changed = True
    while changed:
        changed = False
        for i in range(26):
            if perm[i] == i:
                # Swap with a non-fixed point
                for j in range(i+1, 26):
                    if perm[j] != j:
                        perm[i], perm[j] = perm[j], perm[i]
                        changed = True
                        break
                if changed:
                    break
    return perm

def apply_mapping(word, perm):
    """Apply character mapping to a word using permutation list (perm[i] = what i-th letter maps to)"""
    result = []
    for c in word:
        idx = ord(c) - ord('a')
        result.append(chr(ord('a') + perm[idx]))
    return ''.join(result)

def is_derangement(perm):
    return all(perm[i] != i for i in range(26))

# Try random derangements
count = 0
best_result = None

for attempt in range(5000):
    perm = generate_derangement()

    if not is_derangement(perm):
        print(f"Attempt {attempt}: not a derangement, skipping")
        continue

    # Quick check: count how many words map to valid words
    # Only check words with length >= 4
    matching_count = 0
    matching_words = []
    for word in valid_words:
        if len(word) >= 4:
            mapped = apply_mapping(word, perm)
            if mapped in valid_words:
                matching_count += 1
                matching_words.append(word)

    if matching_count >= 50:
        # Check unique characters
        chars = set()
        for w in matching_words:
            chars.update(w)
        if len(chars) >= 24:
            best_result = (perm, matching_words)
            print(f"SUCCESS at attempt {attempt}: {len(matching_words)} words, {len(chars)} unique chars")
            break

    if attempt % 500 == 0:
        print(f"Attempt {attempt}: {matching_count} matching words")

if best_result:
    perm, words = best_result
    print(f"\nFound solution!")
    print(f"Words count: {len(words)}")
    print(f"Unique chars: {len(set(''.join(words)))}")

    # Create mapping file (26 lines, i-th line is what i-th char maps to)
    with open('/workdir/solution/mapping.txt', 'w') as f:
        for i in range(26):
            f.write(chr(ord('a') + perm[i]) + '\n')

    # Create words file
    with open('/workdir/solution/words.txt', 'w') as f:
        for w in words:
            f.write(w + '\n')

    print("Files created at /workdir/solution/")
else:
    print("No solution found after 5000 attempts")
